CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE municipality(id uuid PRIMARY KEY, name varchar(200) NOT NULL, external_id varchar(200) UNIQUE);
CREATE TABLE department(id uuid PRIMARY KEY, municipality_id uuid NOT NULL REFERENCES municipality, name varchar(200) NOT NULL, UNIQUE(id,municipality_id));
CREATE TABLE app_user(id uuid PRIMARY KEY, municipality_id uuid NOT NULL REFERENCES municipality, department_id uuid, username varchar(100) UNIQUE NOT NULL, password_hash varchar(100) NOT NULL, display_name varchar(200) NOT NULL, role varchar(20) NOT NULL CHECK(role IN ('CITIZEN','OFFICER','LEADER','FIELD','APPROVER','ADMIN')), enabled boolean NOT NULL DEFAULT true, external_id varchar(200), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(department_id,municipality_id) REFERENCES department(id,municipality_id));
CREATE TABLE workflow_version(id uuid PRIMARY KEY, municipality_id uuid NOT NULL REFERENCES municipality, version integer NOT NULL, name varchar(200) NOT NULL, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(municipality_id,version), UNIQUE(id,municipality_id));
CREATE TABLE workflow_transition(workflow_id uuid NOT NULL REFERENCES workflow_version, from_status varchar(40) NOT NULL, action varchar(40) NOT NULL, to_status varchar(40) NOT NULL, role varchar(20) NOT NULL, PRIMARY KEY(workflow_id,from_status,action));
CREATE TABLE category(id uuid PRIMARY KEY, municipality_id uuid NOT NULL REFERENCES municipality, department_id uuid, workflow_id uuid NOT NULL, name varchar(200) NOT NULL, sla_hours integer NOT NULL CHECK(sla_hours BETWEEN 1 AND 87600), fields jsonb NOT NULL DEFAULT '[]', active boolean NOT NULL DEFAULT true, FOREIGN KEY(department_id,municipality_id) REFERENCES department(id,municipality_id), FOREIGN KEY(workflow_id,municipality_id) REFERENCES workflow_version(id,municipality_id), UNIQUE(id,municipality_id));
CREATE TABLE complaint(id uuid PRIMARY KEY, municipality_id uuid NOT NULL REFERENCES municipality, category_id uuid NOT NULL, reporter_id uuid NOT NULL REFERENCES app_user, officer_id uuid REFERENCES app_user, department_id uuid, leader_id uuid REFERENCES app_user, workflow_id uuid NOT NULL, title varchar(200) NOT NULL, description text NOT NULL, address varchar(1000) NOT NULL, location geography(Point,4326), status varchar(40) NOT NULL DEFAULT 'NEW', answers jsonb NOT NULL DEFAULT '{}', version bigint NOT NULL DEFAULT 0, due_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), external_id varchar(200), FOREIGN KEY(category_id,municipality_id) REFERENCES category(id,municipality_id), FOREIGN KEY(department_id,municipality_id) REFERENCES department(id,municipality_id), FOREIGN KEY(workflow_id,municipality_id) REFERENCES workflow_version(id,municipality_id));
CREATE INDEX complaint_geo ON complaint USING gist(location);
CREATE INDEX complaint_scope ON complaint(municipality_id,department_id,status);
CREATE TABLE work_order(id uuid PRIMARY KEY, complaint_id uuid NOT NULL REFERENCES complaint, assignee_id uuid NOT NULL REFERENCES app_user, assigned_by uuid NOT NULL REFERENCES app_user, status varchar(40) NOT NULL DEFAULT 'ASSIGNED', due_at timestamptz NOT NULL, reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_active_work ON work_order(complaint_id) WHERE status NOT IN ('DECLINED','COMPLETE','CANCELLED');
CREATE TABLE resource_request(id uuid PRIMARY KEY, complaint_id uuid NOT NULL REFERENCES complaint, work_order_id uuid NOT NULL REFERENCES work_order, requested_by uuid NOT NULL REFERENCES app_user, approver_id uuid REFERENCES app_user, status varchar(40) NOT NULL DEFAULT 'DRAFT', version bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE resource_revision(id uuid PRIMARY KEY, resource_id uuid NOT NULL REFERENCES resource_request, revision integer NOT NULL, proposal text NOT NULL, amount numeric(14,2) NOT NULL CHECK(amount>=0), duration_days integer NOT NULL CHECK(duration_days>0), submitted_by uuid NOT NULL REFERENCES app_user, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(resource_id,revision));
CREATE TABLE field_report(id uuid PRIMARY KEY, complaint_id uuid NOT NULL REFERENCES complaint, work_order_id uuid NOT NULL REFERENCES work_order, revision integer NOT NULL, content text NOT NULL, submitted_by uuid NOT NULL REFERENCES app_user, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(work_order_id,revision));
CREATE TABLE review(id uuid PRIMARY KEY, complaint_id uuid NOT NULL REFERENCES complaint, resource_id uuid REFERENCES resource_request, report_id uuid REFERENCES field_report, actor_id uuid NOT NULL REFERENCES app_user, stage varchar(40) NOT NULL, decision varchar(40) NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE attachment(id uuid PRIMARY KEY, complaint_id uuid NOT NULL REFERENCES complaint, report_id uuid REFERENCES field_report, resource_id uuid REFERENCES resource_request, uploaded_by uuid NOT NULL REFERENCES app_user, original_name varchar(255) NOT NULL, content_type varchar(100) NOT NULL, size_bytes bigint NOT NULL, sha256 char(64) NOT NULL, storage_key varchar(100) UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE follower(complaint_id uuid NOT NULL REFERENCES complaint,user_id uuid NOT NULL REFERENCES app_user, PRIMARY KEY(complaint_id,user_id));
CREATE TABLE audit_event(id uuid PRIMARY KEY, complaint_id uuid REFERENCES complaint, municipality_id uuid NOT NULL REFERENCES municipality, actor_id uuid NOT NULL REFERENCES app_user, action varchar(60) NOT NULL, from_status varchar(40), to_status varchar(40), reason text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_user,complaint_id uuid NOT NULL REFERENCES complaint,message varchar(300) NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE integration_reference(id uuid PRIMARY KEY, municipality_id uuid NOT NULL REFERENCES municipality, entity_type varchar(40) NOT NULL, local_id uuid NOT NULL, provider varchar(40) NOT NULL, external_id varchar(200) NOT NULL, UNIQUE(municipality_id,provider,entity_type,external_id));
